<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>content</td>
<td>徽标显示的内容</td>
<td><code v-pre>number | string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>max</td>
