<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>text-color</td>
<td>徽标显示的内容颜色</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>type</td>
<td>徽标的类型</td>
<td><code v-pre>'floating' | 'inline'</code></td>
<td style="text-align:center"><code v-pre>floating</code></td>
</tr>
<tr>
<td>position</td>
<td>徽标的位置，type 为 floating 时有效</td>
<td><code v-pre>'top-right' | 'top-left' | 'bottom-right' | 'bottom-left'</code></td>
<td style="text-align:center"><code v-pre>top-right</code></td>
</tr>
<tr>
<td>inline-position</td>
<td>徽标的位置，type 为 inline 时有效</td>
<td><code v-pre>'start' | 'end'</code></td>
<td style="text-align:center"><code v-pre>end</code></td>
</tr>
<tr>
<td>size</td>
<td>徽标的尺寸</td>
<td><code v-pre>'xs' | 'sm' | 'md' | 'lg' | 'xl'</code></td>
<td style="text-align:center"><code v-pre>md</code></td>
</tr>
<tr>
<td>status</td>
<td>徽标的状态</td>
<td><code v-pre>'default' | 'success' | 'warning' | 'danger'</code></td>
<td style="text-align:center"><code v-pre>danger</code></td>
</tr>
<tr>
<td>show</td>
<td>是否显示徽标</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>true</code></td>
</tr>
<tr>
<td>show-zero</td>
<td>徽标为0时是否显示</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>variant</td>
<td>徽标的变体</td>
<td><code v-pre>'outline' | 'default'</code></td>
<td style="text-align:center"><code v-pre>default</code></td>
</tr>
</tbody>
</table>
